    safetyTitle: 'Почему это безопасно',
    safetyDesc: 'По умолчанию Shroudly не требует ни драйвера, ни прав администратора: во время работы он лишь направляет систему на локальный прокси и восстанавливает прежнюю настройку при остановке, сбое или выходе из системы, поэтому подключение никогда не остаётся неработающим. Расширенный режим необязателен и работает, только если вы его включите.',
