    // ── About screen
    systemStatus: 'État du système',
    howItWorks: 'Fonctionnement',
    technique_frag: 'Fragmentation TCP',
    technique_frag_desc: 'Le premier paquet TCP de chaque connexion est découpé en petits segments. Les systèmes DPI qui ne réassemblent pas les flux TCP ne peuvent pas lire le champ Host/SNI en entier et laissent passer la connexion.',
    technique_disorder: 'Désordre',
    technique_disorder_desc: 'Les segments sont envoyés dans le désordre (le dernier en premier). La pile TCP du destinataire les remet correctement en ordre, mais les systèmes DPI qui lisent les paquets dans l’ordre ne peuvent pas identifier la connexion.',
    technique_dns: 'DNS anti-empoisonnement',
    technique_dns_desc: 'Les noms sont résolus simultanément via plusieurs résolveurs publics indépendants et les réponses falsifiées sont écartées : le blocage par DNS est ainsi déjoué sans modifier les paramètres DNS de votre système.',
    technique_http: 'Brouillage de l’en-tête HTTP Host',
    technique_http_desc: 'Pour les connexions HTTP non chiffrées, l’en-tête "Host:" est réécrit en "hoSt:". Les systèmes DPI simples qui recherchent le texte exact "Host:" ne le trouvent plus.',
    safetyTitle: 'Pourquoi c’est sûr',
    safetyDesc: 'Par défaut, Shroudly ne nécessite ni pilote ni droits d’administrateur : lorsqu’il est actif, il se contente de diriger votre système vers un proxy local, puis rétablit le réglage précédent à l’arrêt, en cas de plantage ou à la fermeture de session. Votre connexion n’est donc jamais laissée hors service. Le mode avancé est facultatif et ne s’exécute que si vous l’activez.',
    footerProduct: 'Un produit {brand}',
    technique_probe: 'Recherche automatique de stratégie',
