    cutBodyAdvanced: 'Dieses Netz verfolgt ganze Verbindungen, nicht nur ihren Anfang. Shroudly probiert für diese Seite bereits andere Techniken; der erweiterte Modus arbeitet darunter und kommt meist durch.',
    cutBodyAdvancedOn: 'Der erweiterte Modus ist an, und das Netz trennt trotzdem. Höchstwahrscheinlich ist die Adresse des Servers gesperrt, und die kann keine Technik ändern; für diese Seite kommt nur ein VPN durch.',
