    routeAppliesNow: 'Зміни маршрутизації застосовуються одразу.',
    obTitle1: 'Вітаємо в Shroudly',
    obBody1: 'Коли сайт заблоковано, провайдер зазвичай розпізнає його за назвою сайту у вашому найпершому пакеті або дає неправдиву відповідь на ваш DNS-запит. Shroudly змінює форму цього пакета й шукає адреси через зашифрований DNS, тож сайт завантажується як звичайно. Ваш трафік і далі йде безпосередньо до сайту — це не VPN, і Shroudly не приховує, хто ви.',
    obTitle2: 'Одна кнопка',
    obBody2: 'Натисніть «Увімкнути захист» — і, поки Shroudly працює, ваша система спрямовується через нього. Натисніть «Вимкнути захист» — і мережеві налаштування повернуться точно такими, як були. Їх буде відновлено й тоді, коли програма аварійно завершить роботу, її примусово закриють або зникне живлення. Вам ніколи не доведеться нічого скасовувати вручну.',
    obTitle3: 'Які сайти йдуть через Shroudly',
    obBody3: 'Типово всі сайти йдуть через Shroudly, а незаблокований сайт передається далі без змін — тож нічого не сповільнюється, а заблокований сайт працює, навіть якщо ви ніколи про нього не чули. У налаштуваннях можна натомість обмежитися списком сайтів і будь-коли додавати чи вилучати сайти з нього.',
    obTitle4: 'Якщо сайт усе одно не відкривається',
    obBody4: 'Відкрийте налаштування й скористайтеся перевіркою сайту: вона справді пробує відкрити сайт і показує, що його блокує. На вкладці «Журнал» записано, що сталося з кожним сайтом, — саме це нам потрібно, якщо ви повідомляєте про проблему. У Windows і Linux також є розширений режим для мереж, які звичайний режим не може обійти.',
