    regionBody: 'Такія фільтры сочаць за злучэннямі цалкам, і звычайны рэжым не заўсёды можа іх абысці. Пашыраны рэжым працуе на ніжэйшым узроўні і створаны якраз для іх. Ён адзін раз запытвае дазвол адміністратара.',
