    discordModeLabel: 'Sepana Discord',
    discordModeDesc: 'Dihêle ku sepana Discord di ser Shroudly re nû bibe û vebe. Rêzekê li pelê mîhengan ê Discordê zêde dike; neçalakkirina vê wê radike.',
    discordOfferTitle: 'Ma sepana Discord li ser “Checking for updates” asê maye?',
    discordOfferBody: 'Nûkera Discordê Shroudly paşguh dike, ji ber vê yekê fîltre hîn jî wê disekinîne. Shroudly dikare bi zêdekirina rêzekê li pelê mîhengan ê Discordê wê di ser xwe re derbas bike. Dema tu ji Shroudly derkevî an vê di Mîhengan de neçalak bikî, ew rêz tê rakirin.',
