    appBrowserNote: 'Heke tu Roblox an sazkera wê ji gerokê dest pê dikî, pêşî gerokê bi tevahî bigire û dîsa veke.',
    appOfferTitle: 'Ma Roblox di gerokê de vedibe lê wekî sepan venabe?',
